param(
  [ValidateSet('x64', 'x86')][string]$Architecture = 'x64',
  [string]$VcVarsVer = '14.29'
)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$metadata = Get-Content (Join-Path $repoRoot 'config/backend.json') -Raw | ConvertFrom-Json

if ($metadata.PSObject.Properties.Name -contains 'source_build') {
  # The reviewed GPL candidates are C++ changes to the pinned GPLALL source.
  # Build that source for each architecture; never silently fall back to the
  # older prebuilt archive when source-build metadata is present.
  $built = & (Join-Path $PSScriptRoot 'build_gplall_source.ps1') -Architecture $Architecture -VcVarsVer $VcVarsVer
  if ($LASTEXITCODE -ne 0) { throw "GPLALL source build failed: $LASTEXITCODE" }
  $paths = @($built | Where-Object { $_ -is [string] -and $_.Trim() })
  if ($paths.Count -ne 1 -or !(Test-Path -LiteralPath $paths[0])) {
    throw 'GPLALL source build did not return exactly one backend path'
  }
  Write-Output $paths[0]
  exit 0
}

$directory = Join-Path $repoRoot '.deps/gplall'
$archive = Join-Path $directory 'backend.zip'
$extracted = Join-Path $directory 'release'
New-Item -ItemType Directory -Force $directory | Out-Null
if (-not (Test-Path -LiteralPath $archive)) {
  Invoke-WebRequest -UseBasicParsing -Uri $metadata.url -OutFile $archive
}
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLower() -ne $metadata.sha256) {
  throw 'DXVK-GPLALL archive checksum mismatch; preserve or move the archive before retrying.'
}
# Expand the verified archive each time to avoid reusing modified extracted files.
Expand-Archive -LiteralPath $archive -DestinationPath $extracted -Force
$relative = if ($Architecture -eq 'x86') { 'x32/d3d9.dll' } else { 'x64/d3d9.dll' }
$backend = Join-Path $extracted $relative
if (-not (Test-Path -LiteralPath $backend)) { throw "Release has no $relative" }
$expected = $metadata.files.PSObject.Properties[$relative].Value
if (!$expected -or (Get-FileHash -LiteralPath $backend -Algorithm SHA256).Hash.ToLower() -ne $expected) {
  throw "DXVK-GPLALL $Architecture file checksum mismatch"
}
if ($metadata.PSObject.Properties.Name -contains 'modification') {
  # Keep the verified upstream DLL separate. The recipe fails closed on any
  # source/shader/offset/output mismatch and never patches an installed game.
  $modified = Join-Path $directory "modified/$($metadata.modification.id)/$Architecture/d3d9.dll"
  $prepared = & python (Join-Path $PSScriptRoot 'backend_recipe.py') --input $backend --output $modified --architecture $Architecture
  if ($LASTEXITCODE -ne 0) { throw "DXVK-GPLALL $Architecture shader recipe failed" }
  if (@($prepared).Count -ne 1 -or !(Test-Path -LiteralPath $prepared)) {
    throw 'Backend recipe did not return one prepared DLL'
  }
  $backend = $prepared
}
Write-Output $backend
